import {StyleSheet,Text,View} from '@/platform/react-native';
import {Card,Muted,Screen,useAppTheme} from '@/components/UI';

export type PolicySection={heading:string;paragraphs:string[]};
export function PolicyPage({intro,sections,updated='30 August 2026'}:{intro:string;sections:PolicySection[];updated?:string}){const{palette}=useAppTheme();return <Screen scroll contentStyle={s.page}><Muted style={s.intro}>{intro}</Muted><Muted style={s.updated}>Last updated: {updated}</Muted>{sections.map(section=><Card key={section.heading} style={s.card}><Text style={[s.heading,{color:palette.text}]}>{section.heading}</Text>{section.paragraphs.map(paragraph=><View key={paragraph} style={s.row}><View style={[s.bullet,{backgroundColor:palette.success}]}/><Text style={[s.body,{color:palette.text}]}>{paragraph}</Text></View>)}</Card>)}<Muted style={s.contact}>Questions about this document can be sent to support@cdaconnect.org.</Muted></Screen>}
const s=StyleSheet.create({page:{width:'100%',maxWidth:820,alignSelf:'center',paddingBottom:120},intro:{fontSize:16,lineHeight:23},updated:{fontSize:13,marginTop:6,marginBottom:14},card:{marginBottom:12},heading:{fontSize:19,fontWeight:'900',marginBottom:12},row:{flexDirection:'row',alignItems:'flex-start',gap:9,marginBottom:10},bullet:{width:7,height:7,borderRadius:4,marginTop:8,flexShrink:0},body:{flex:1,minWidth:0,fontSize:15,lineHeight:23},contact:{textAlign:'center',marginTop:4}});
